from pathlib import Pathimport jsonimport osimport timeimport requestsimport pandas as pdimport numpy as npROOT = Path(__file__).resolve().parent.parentRAW = ROOT / 'data' / 'raw'RAW.mkdir(parents=True, exist_ok=True)SAMPLE_FILE = RAW / 'multisat_2024_sample.csv'HISTORY_FILE = RAW / 'multisat_2024_gp_history.json'SNAPSHOT_FILE = RAW / 'multisat_2024_snapshot.json'SATCAT_FILE = RAW / 'multisat_2024_satcat.json'LOGIN_URL = 'https://www.space-track.org/ajaxauth/login'BASE = 'https://www.space-track.org/basicspacedata/query'# Use UTC windows. April 25 to May 22 provides pre/post storm days.START, END = '2024-04-25', '2024-05-22'BANDS = [(200, 350), (350, 500), (500, 650), (650, 800)]PER_BAND = 25SEED = 2024def get_json(session, path):    response = session.get(BASE + path, timeout=180)    response.raise_for_status()    try:        result = response.json()    except ValueError as e:        raise RuntimeError('Space-Track returned non-JSON. Check login/session.') from e    if isinstance(result, dict):        raise RuntimeError(f'Space-Track message: {str(result)[:300]}')    if not isinstance(result, list):        raise RuntimeError('Expected a list of records from Space-Track.')    return resultdef get_login():    username = os.getenv('SPACETRACK_USERNAME')    password = os.getenv('SPACETRACK_PASSWORD')    if not username or not password:        raise RuntimeError('Set SPACETRACK_USERNAME and SPACETRACK_PASSWORD in your terminal first.')    session = requests.Session()    r = session.post(LOGIN_URL, data={'identity': username, 'password': password}, timeout=30)    r.raise_for_status()    try:        payload = r.json()    except ValueError:        payload = None    if isinstance(payload, dict) and str(payload.get('Login', '')).lower() == 'failed':        raise RuntimeError('Space-Track rejected login credentials.')    return sessiondef read_or_fetch(session, path, file):    if file.exists():        print('Using cached', file.name)        return json.loads(file.read_text())    print('Fetching', file.name)    rows = get_json(session, path)    file.write_text(json.dumps(rows, indent=2))    return rowsdef altitude_km(mean_motion):    n = float(mean_motion) * 2 * np.pi / 86400    return (398600.4418 / n**2)**(1 / 3) - 6371.0def select_sample(session):    if SAMPLE_FILE.exists():        print('Using cached sample:', SAMPLE_FILE)        return pd.read_csv(SAMPLE_FILE)    # Sample historical May 1 objects, rather than choosing only currently active satellites.    # A cap may truncate coverage; this is an exploratory, NOT representative sample.    snapshot = read_or_fetch(        session,        '/class/gp_history/EPOCH/2024-05-01--2024-05-02'        '/MEAN_MOTION/13--17/orderby/NORAD_CAT_ID%20asc,EPOCH%20asc'        '/limit/10000/format/json',        SNAPSHOT_FILE,    )    print('Snapshot records:', len(snapshot))    if len(snapshot) == 10000:        print('WARNING: snapshot hit 10,000 record cap; selection may be biased.')    candidates = pd.DataFrame(snapshot)    if candidates.empty:        raise RuntimeError('No satellite candidates returned.')    candidates['NORAD_CAT_ID'] = pd.to_numeric(candidates['NORAD_CAT_ID'], errors='coerce')    candidates['MEAN_MOTION'] = pd.to_numeric(candidates['MEAN_MOTION'], errors='coerce')    candidates = candidates.dropna(subset=['NORAD_CAT_ID', 'MEAN_MOTION'])    candidates['altitude_km'] = candidates['MEAN_MOTION'].apply(altitude_km)    candidates = candidates.sort_values('EPOCH').drop_duplicates('NORAD_CAT_ID', keep='last')    candidates = candidates[candidates['altitude_km'].between(200, 800, inclusive='left')].copy()    # Filter to cataloged payloads rather than debris / rocket bodies.    ids = candidates['NORAD_CAT_ID'].astype(int).astype(str).tolist()    satcat = []    for i in range(0, len(ids), 100):        satcat.extend(get_json(session, f"/class/satcat/NORAD_CAT_ID/{','.join(ids[i:i+100])}/format/json"))        time.sleep(3)    SATCAT_FILE.write_text(json.dumps(satcat, indent=2))    payload_ids = {        int(x['NORAD_CAT_ID']) for x in satcat        if x.get('NORAD_CAT_ID') and str(x.get('OBJECT_TYPE', '')).upper() == 'PAYLOAD'    }    candidates = candidates[candidates['NORAD_CAT_ID'].astype(int).isin(payload_ids)]    rng = np.random.default_rng(SEED)    picks = []    for low, high in BANDS:        group = candidates[(candidates.altitude_km >= low) & (candidates.altitude_km < high)]        n = min(PER_BAND, len(group))        if n:            selected = group.iloc[rng.choice(len(group), size=n, replace=False)].copy()            selected['altitude_band'] = f'{low}-{high} km'            picks.append(selected)        print(f'{low}-{high} km: {len(group)} candidates, {n} selected')    if not picks:        raise RuntimeError('No payloads found in the target altitude bins.')    sample = pd.concat(picks, ignore_index=True)    sample = sample[['NORAD_CAT_ID', 'OBJECT_NAME', 'EPOCH', 'altitude_km', 'altitude_band']]    sample.to_csv(SAMPLE_FILE, index=False)    print('Saved sample:', SAMPLE_FILE, '\nNumber selected:', len(sample))    return sampledef main():    with get_login() as session:        sample = select_sample(session)        if HISTORY_FILE.exists():            print('Existing historical download found:', HISTORY_FILE)            print('Delete it only if you intentionally need to change the sample/date range.')            return        ids = sorted(sample['NORAD_CAT_ID'].astype(int).astype(str).tolist())        # Include known CIRBE case even if it was not randomly sampled.        if '56188' not in ids:            ids.append('56188')        all_records = []        for i in range(0, len(ids), 20):            chunk = ids[i:i+20]            print(f'Downloading satellite histories {i+1}-{min(i+20,len(ids))}/{len(ids)}')            path = (f"/class/gp_history/NORAD_CAT_ID/{','.join(chunk)}"                    f'/EPOCH/{START}--{END}/orderby/NORAD_CAT_ID%20asc,EPOCH%20asc/format/json')            all_records.extend(get_json(session, path))            time.sleep(4)        if not all_records:            raise RuntimeError('Space-Track returned no historical elements.')        HISTORY_FILE.write_text(json.dumps(all_records, indent=2))        print('Saved', len(all_records), 'records to', HISTORY_FILE)        print('Next: python src/analyze_multisat_2024.py')if __name__ == '__main__':    main()